<?php
declare(strict_types=1);require '../config/db.php';require '../config/auth.php';require_role('admin','login.php');
$id=(int)($_GET['id']??0);
$s=$pdo->prepare("SELECT a.reference_no,a.appointment_date,a.start_time,a.end_time,a.status,a.payment_method,a.payment_status,u.full_name parishioner,s.name service_name,b.* FROM appointments a JOIN users u ON u.id=a.user_id JOIN services s ON s.id=a.service_id LEFT JOIN baptism_booking_details b ON b.appointment_id=a.id WHERE a.id=? AND LOWER(s.name)='baptism'");$s->execute([$id]);$b=$s->fetch();if(!$b){http_response_code(404);exit('Baptism booking details not found.');}
$additional=$b['additional_godparents']?json_decode($b['additional_godparents'],true):[];if(!is_array($additional))$additional=[];
