<section class="grid two"><div class="card"><h2>Child & parents</h2><small class="muted">Child</small><p><b><?=e($b['child_full_name'])?></b><br><?=date('F j, Y',strtotime($b['child_dob']))?><br><?=e($b['child_birth_place'])?></p><div class="grid two"><div><small class="muted">Father</small><p><?=e($b['father_full_name'])?></p></div><div><small class="muted">Mother's maiden name</small><p><?=e($b['mother_maiden_name'])?></p></div></div><small class="muted">Parents' status</small><p><?=e($b['parents_marriage_status'])?></p><small class="muted">Contact</small><p><?=e($b['contact_number'])?> · <?=e($b['contact_email'])?></p></div>
<div class="card"><h2>Baptism & schedule</h2><small class="muted">Type</small><p><b><?=e($b['baptism_type'])?></b></p><small class="muted">Schedule</small><p><?=date('F j, Y',strtotime($b['appointment_date']))?> · <?=date('g:i A',strtotime($b['start_time']))?>–<?=date('g:i A',strtotime($b['end_time']))?></p><small class="muted">Payment</small><p><?=e(ucfirst($b['payment_method']))?> · <?=e(str_replace('_',' ',$b['payment_status']))?></p></div></section>
